-- Better Auth 1.7.12 core + JWT: generated by frontend/scripts/auth-schema.mjs
CREATE TABLE auth."user" (
id text PRIMARY KEY,
"name" text NOT NULL,
"email" text NOT NULL UNIQUE,
"emailVerified" boolean NOT NULL,
"image" text,
"createdAt" timestamptz NOT NULL,
"updatedAt" timestamptz NOT NULL
);
CREATE TABLE auth."session" (
id text PRIMARY KEY,
"expiresAt" timestamptz NOT NULL,
"token" text NOT NULL UNIQUE,
"createdAt" timestamptz NOT NULL,
"updatedAt" timestamptz NOT NULL,
"ipAddress" text,
"userAgent" text,
"userId" text NOT NULL REFERENCES auth."user"("id") ON DELETE CASCADE
);
CREATE INDEX ON auth."session" ("userId");
CREATE TABLE auth."account" (
id text PRIMARY KEY,
"accountId" text NOT NULL,
"providerId" text NOT NULL,
"userId" text NOT NULL REFERENCES auth."user"("id") ON DELETE CASCADE,
"accessToken" text,
"refreshToken" text,
"idToken" text,
"accessTokenExpiresAt" timestamptz,
"refreshTokenExpiresAt" timestamptz,
"scope" text,
"password" text,
"createdAt" timestamptz NOT NULL,
"updatedAt" timestamptz NOT NULL
);
CREATE INDEX ON auth."account" ("userId");
CREATE TABLE auth."verification" (
id text PRIMARY KEY,
"identifier" text NOT NULL,
"value" text NOT NULL,
"expiresAt" timestamptz NOT NULL,
"createdAt" timestamptz NOT NULL,
"updatedAt" timestamptz NOT NULL
);
CREATE INDEX ON auth."verification" ("identifier");
CREATE TABLE auth."jwks" (
id text PRIMARY KEY,
"publicKey" text NOT NULL,
"privateKey" text NOT NULL,
"createdAt" timestamptz NOT NULL,
"expiresAt" timestamptz,
"alg" text,
"crv" text
);
CREATE UNIQUE INDEX account_provider_identity ON auth.account ("providerId", "accountId");
CREATE UNIQUE INDEX one_google_per_user ON auth.account ("userId") WHERE "providerId"='google';
